export default class t{constructor(t=50){this.limit=t,this.past=[],this.future=[]}get canUndo(){return this.past.length>0}get canRedo(){return this.future.length>0}push(t){this.past.push(t),this.past.length>this.limit&&this.past.shift(),this.future=[]}undo(t){return this.canUndo?(this.future.push(t),this.past.pop()):null}redo(t){return this.canRedo?(this.past.push(t),this.future.pop()):null}clear(){this.past=[],this.future=[]}}